<?php
require __DIR__.'/library_network_bootstrap.php';require __DIR__.'/iplm_task4_support.php';require APPPATH.'models/Library_activation_model.php';require APPPATH.'models/Auth_model.php';require APPPATH.'models/Iplm_model.php';
$dir=$argv[1]??'';network_check(preg_match('#^/tmp/pustaka_network_test_[a-zA-Z0-9_]+$#D',$dir)&&is_file($dir.'/connection.php'),'Isolated runtime required');$params=require $dir.'/connection.php';network_check(strpos($params['database'],'pustaka_network_test_')===0,'Test DB required');$db=DB($params);$db->db_debug=false;$m=new Library_activation_model();$m->db=$db;$auth=new Auth_model();$auth->db=$db;$iplm=new Iplm_model();$iplm->db=$db;$checks=0;
function ok4($v,$msg){global$checks;network_check($v,'FAIL '.$msg);$checks++;echo 'PASS '.$msg,PHP_EOL;}
function reject4($fn,$msg){$failed=false;try{$fn();}catch(Throwable$e){$failed=true;}ok4($failed,$msg);}
ok4($db->count_all('library_source_records')===834,'All 834 source rows archived, including held rows');
